UPDATE pull_task_group_execution
SET lock_owner = #{criteria.lease.lockOwner},
    lock_expires_at = #{criteria.lease.lockExpiresAt},
    updated_at = #{criteria.lease.now}
WHERE (

    (execution_status = #{state.executionStatus}
     AND stage IN

       #{stage}
     )

)
  AND manual_paused = #{criteria.eligibleManualPaused}
  AND next_run_at <= #{criteria.lease.now}
  AND (lock_owner IS NULL OR lock_expires_at <= #{criteria.lease.now})
  AND EXISTS (
    SELECT 1
    FROM pull_task parent_task
    WHERE parent_task.id = pull_task_group_execution.task_id
      AND parent_task.tenant_id = pull_task_group_execution.tenant_id
      AND parent_task.deleted_at IS NULL
      AND parent_task.task_type = #{criteria.parent.taskType}
      AND parent_task.mode = #{criteria.parent.taskMode}
      AND parent_task.status = #{criteria.parent.taskStatus}
  )
ORDER BY next_run_at ASC, id ASC
LIMIT #{criteria.lease.limit}

mapper.select:
SELECT *
FROM pull_task_group_execution
WHERE lock_owner = #{lockOwner}
  AND lock_expires_at > #{now}
ORDER BY id ASC

SELECT execution_row.*
FROM pull_task_group_execution execution_row
WHERE execution_row.execution_status IN
  #{status}
  AND EXISTS (
    SELECT 1
    FROM pull_task parent_task
    WHERE parent_task.id = execution_row.task_id
      AND parent_task.tenant_id = execution_row.tenant_id
      AND parent_task.deleted_at IS NULL
      AND parent_task.task_type = #{criteria.parent.taskType}
      AND parent_task.mode = #{criteria.parent.taskMode}
  )
  AND (
    EXISTS (
      SELECT 1
      FROM pull_task_account_action action_row
      WHERE action_row.tenant_id = execution_row.tenant_id
        AND action_row.group_execution_id = execution_row.id
        AND (action_row.action_status = #{criteria.facts.action.unknown}
          OR (action_row.action_status = #{criteria.facts.action.submitted}
            AND action_row.submitted_at <= #{criteria.scope.submittedCutoff}))
    )
    OR EXISTS (
      SELECT 1
      FROM pull_task_pull_call call_row
      WHERE call_row.tenant_id = execution_row.tenant_id
        AND call_row.group_execution_id = execution_row.id
        AND (call_row.call_status = #{criteria.facts.call.unknown}
          OR (call_row.call_status = #{criteria.facts.call.submitted}
            AND call_row.submitted_at <= #{criteria.scope.submittedCutoff}))
    )
    OR EXISTS (
      SELECT 1
      FROM pull_task_material_member material_row
      WHERE material_row.tenant_id = execution_row.tenant_id
        AND material_row.group_execution_id = execution_row.id
        AND (
          material_row.pull_status = #{criteria.facts.material.pullUnknown}
          OR material_row.admin_status = #{criteria.facts.material.adminUnknown}
          OR (material_row.admin_status = #{criteria.facts.material.adminSubmitted}
            AND material_row.updated_at <= #{criteria.scope.submittedCutoff})
          OR (material_row.pull_status = #{criteria.facts.material.pullSubmitted}
            AND EXISTS (
              SELECT 1
              FROM pull_task_pull_call material_call
              WHERE material_call.tenant_id = material_row.tenant_id
                AND material_call.id = material_row.pull_call_id
                AND material_call.submitted_at <= #{criteria.scope.submittedCutoff}
            ))
        )
    )
    OR EXISTS (
      SELECT 1
      FROM pull_task_group_account account_row
      WHERE account_row.tenant_id = execution_row.tenant_id
        AND account_row.group_execution_id = execution_row.id
        AND (
          account_row.membership_status = #{criteria.facts.account.membershipUnknown}
          OR account_row.admin_status = #{criteria.facts.account.adminUnknown}
          OR (account_row.admin_status = #{criteria.facts.account.adminSubmitted}
            AND account_row.updated_at <= #{criteria.scope.submittedCutoff})
          OR (account_row.membership_status = #{criteria.facts.account.membershipSubmitted}
            AND account_row.updated_at <= #{criteria.scope.submittedCutoff})
        )
    )
  )
ORDER BY execution_row.id ASC
LIMIT #{criteria.scope.limit}

mapper.update:
UPDATE pull_task_group_execution
SET execution_status = #{targetExecutionStatus},
    started_at = COALESCE(started_at, #{row.startedAt}),
    version = version + 1,
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND execution_status = #{expectedExecutionStatus}
  AND stage = #{expectedStage}
  AND version = #{row.version}
  AND lock_owner = #{row.lockOwner}
  AND lock_expires_at > #{row.updatedAt}

UPDATE pull_task_group_execution
SET execution_status = #{row.executionStatus},
    stage = #{row.stage},
    group_jid = COALESCE(#{row.groupJid}, group_jid),
    next_manager_index = COALESCE(#{row.nextManagerIndex}, next_manager_index),
    next_puller_index = COALESCE(#{row.nextPullerIndex}, next_puller_index),
    wait_resource_type = #{row.waitResourceType},
    reason_code = #{row.reasonCode},
    reason_message = #{row.reasonMessage},
    next_run_at = #{row.nextRunAt},
    finished_at = #{row.finishedAt},
    last_business_executed_at = COALESCE(
      #{row.lastBusinessExecutedAt}, last_business_executed_at),
    lock_owner = NULL,
    lock_expires_at = NULL,
    version = version + 1,
    updated_at = #{row.updatedAt}
WHERE id = #{row.id}
  AND execution_status = #{expectedExecutionStatus}
  AND stage = #{expectedStage}
  AND version = #{row.version}
  AND lock_owner = #{row.lockOwner}
  AND lock_expires_at > #{row.updatedAt}

UPDATE pull_task_group_execution
SET next_manager_index = #{nextManagerIndex},
    next_puller_index = #{nextPullerIndex},
    stage = #{stage},
    next_run_at = #{nextRunAt},
    last_business_executed_at = #{now},
    version = version + 1,
    updated_at = #{now}
WHERE id = #{id}
  AND version = #{expectedVersion}

UPDATE pull_task_group_execution
SET execution_status = #{transition.target.executionStatus},
    stage = #{transition.target.stage},
    group_jid = COALESCE(#{transition.target.groupJid}, group_jid),
    wait_resource_type = #{transition.target.waitResourceType},
    reason_code = #{transition.target.reasonCode},
    reason_message = #{transition.target.reasonMessage},
    next_run_at = #{transition.target.nextRunAt},
    finished_at = #{transition.target.finishedAt},
    last_business_executed_at = #{transition.now},
    version = version + 1,
    updated_at = #{transition.now}
WHERE id = #{transition.executionId}
  AND task_id = #{transition.taskId}
  AND version = #{transition.expectedVersion}
  AND execution_status = #{transition.expected.executionStatus}
  AND stage = #{transition.expected.stage}
  AND lock_owner IS NULL

